from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for character-prefix reuse in serialized rows."""

    def __init__(self, df: pd.DataFrame = None):
        """Store only lightweight metadata; the input frame is never modified."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a cell exactly as scoring does, mapping scalar missing values to ''."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(a: str, b: str) -> int:
        """Compute a common-prefix length with logarithmically many C-level slice comparisons."""
        hi = min(len(a), len(b))
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if a[:mid] == b[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings: List[str]) -> int:
        """Return exact ideal Trie reuse as LCP lengths of lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _key_stats(values, rows=None):
        """Return length-weighted pair repetition for a whole column or a row subset."""
        counts = {}
        if rows is None:
            iterator = values
        else:
            iterator = (values[r] for r in rows)
        for value in iterator:
            counts[value] = counts.get(value, 0) + 1
        return sum(len(v) * k * (k - 1) for v, k in counts.items())

    def _global_order(self, cells, variant: int) -> List[int]:
        """Build a deterministic global column order using pair repetition statistics."""
        n, m = cells.shape
        ranked = []
        for c in range(m):
            counts = {}
            total_length = 0
            for value in cells[:, c]:
                counts[value] = counts.get(value, 0) + 1
                total_length += len(value)

            pairs = sum(k * (k - 1) for k in counts.values())
            weighted = sum(len(v) * k * (k - 1)
                           for v, k in counts.items())

            if variant == 0:
                metric = weighted
            elif variant == 1:
                # A distinct proposal that favors repeated long values but mildly
                # rewards columns having a larger repeated population.
                metric = weighted + pairs * max(1, total_length // max(1, n))
            else:
                # Prefer columns with useful character mass while avoiding a
                # pathological preference for a single enormous value.
                metric = weighted + 2 * pairs

            ranked.append((metric, pairs, c))

        return [c for _, _, c in sorted(
            ranked, key=lambda x: (-x[0], -x[1], x[2])
        )]

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Recursively partition rows by repeated fields and choose suffixes per group."""
        n, m = cells.shape
        result = [None] * n
        if m == 0:
            return [[] for _ in range(n)]

        # The bounded recursion deliberately examines only a small number of
        # promising fields per node.  Statistics are computed from cached cell
        # strings and no pandas objects are created in the loop.
        max_depth = min(4, m)
        max_candidates = min(8, m)

        def visit(rows, remaining, prefix, depth):
            if not rows:
                return
            if not remaining or depth >= max_depth or len(rows) <= 2:
                tail = sorted(
                    remaining,
                    key=lambda c: (-self._key_stats(cells[:, c], rows), c)
                )
                order = prefix + tail
                for r in rows:
                    result[r] = order[:]
                return

            choices = []
            for c in remaining:
                counts = {}
                for r in rows:
                    value = cells[r, c]
                    counts[value] = counts.get(value, 0) + 1
                repeated = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                pair_count = sum(
                    count * (count - 1) for count in counts.values()
                )
                choices.append((repeated, pair_count, c))

            choices.sort(key=lambda x: (-x[0], -x[1], x[2]))
            # If no field can create a shared character prefix, further
            # partitioning cannot improve this group's leading reuse.
            selected = choices[:max_candidates]
            if not selected or selected[0][0] <= 0:
                tail = [c for _, _, c in sorted(
                    choices, key=lambda x: (-x[1], x[2])
                )]
                order = prefix + tail
                for r in rows:
                    result[r] = order[:]
                return

            lead = selected[0][2]
            groups = {}
            for r in rows:
                groups.setdefault(cells[r, lead], []).append(r)

            rest = [c for c in remaining if c != lead]
            # Singleton groups are cheap and need no recursive statistics.
            for group in groups.values():
                visit(group, rest, prefix + [lead], depth + 1)

        visit(list(range(n)), list(range(m)), [], 0)
        return result

    def _materialize(self, raw, cells, orders):
        """Create row strings and return their exact Trie score and lexicographic order."""
        n = raw.shape[0]
        strings = [
            "".join(cells[r, c] for c in orders[r])
            for r in range(n)
        ]
        score = self._score(strings)
        row_order = sorted(range(n), key=lambda r: (strings[r], r))
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Evaluate two global and one conditional lossless permutation hypotheses."""
        n, m = df.shape
        self.num_rows, self.num_cols = n, m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)
        for r in range(n):
            for c in range(m):
                cells[r, c] = self._cell_text(raw[r, c])

        global_a = self._global_order(cells, 0)
        global_b = self._global_order(cells, 1)
        conditional = self._conditional_orders(cells)

        candidates = (
            [[global_a[:] for _ in range(n)],
             [global_b[:] for _ in range(n)],
             conditional]
        )

        best = None
        for orders in candidates:
            score, strings, row_order = self._materialize(raw, cells, orders)
            signature = tuple(orders[0]) if orders else ()
            # Score dominates; signatures provide deterministic tie-breaking.
            choice = (score, tuple(-c for c in signature))
            if best is None or choice > best[0]:
                best = (choice, row_order, orders)

        _, row_order, orders = best
        output = np.empty((n, m), dtype=object)
        output_orders = []

        for destination, source in enumerate(row_order):
            order = orders[source]
            output[destination, :] = [raw[source, c] for c in order]
            output_orders.append([df.columns[c] for c in order])

        # Object construction preserves mixed types and the original cell values.
        result = pd.DataFrame(output, columns=df.columns, index=None)
        return result, output_orders


